export type McpVerifyResult = {
    ok: true;
    servers: Array<{
        name: string;
        tools: number;
    }>;
} | {
    ok: false;
    errors: Array<{
        server: string;
        error: string;
    }>;
};
export interface McpServerConfig {
    name: string;
    url?: string;
    transport?: 'sse' | 'streamableHttp';
    command?: string;
    args?: string[];
    env?: Record<string, string>;
    headers?: Record<string, string>;
    connectionTimeoutMs?: number;
    requireApproval?: string[] | boolean;
}
